// Validate incoming RoadSense report payload structure
const body = $input.first().json.body || $input.first().json;

if (!body.reportId || !body.latitude || !body.longitude || !body.category) {
  throw new NodeOperationError(this, 'Invalid payload: reportId, latitude, longitude, and category are required.');
}

// Idempotency key tracking
const eventId = body.eventId || `evt_${body.reportId}`;

return {
  json: {
    eventId,
    reportId: body.reportId,
    hazardId: body.hazardId || null,
    userId: body.userId || 'anonymous',
    category: body.category,
    additionalLabel: body.additionalLabel || null,
    severity: body.severity || 'high',
    latitude: Number(body.latitude),
    longitude: Number(body.longitude),
    address: body.address || 'Unknown',
    locality: body.locality || 'Bengaluru',
    imageUrl: body.imageUrl || '',
    aiClassification: body.aiClassification || null,
    sensorTriggered: Boolean(body.sensorTriggered),
    timestamp: body.timestamp || new Date().toISOString(),
    processedAt: new Date().toISOString()
  }
};

// Special tagging for waterlogged roads: represent uncertainty honestly
const item = $input.first().json;
item.additionalLabel = 'POTENTIALLY_HIDDEN_SURFACE_HAZARD';
item.advisoryMessage = 'Waterlogged road ahead. Road surface may be uneven. Proceed cautiously.';
item.triagePriority = 'CRITICAL_UNSEEN_DEPTH';
item.processingStatus = 'PROCESSED_WATERLOG_FLAGGED';
return { json: item };

// Standard hazard processing logic
const item = $input.first().json;
item.advisoryMessage = `${item.category.replace('_', ' ')} reported ahead near ${item.locality}.`;
item.triagePriority = item.severity === 'critical' ? 'HIGH' : 'NORMAL';
item.processingStatus = 'PROCESSED_ACTIVE';
return { json: item };

// Prepare final audit and database update response
const input = $input.first().json;

return {
  json: {
    status: 'success',
    workflowName: 'RoadSense — New Hazard Report Processor',
    eventId: input.eventId,
    reportId: input.reportId,
    hazardId: input.hazardId,
    category: input.category,
    additionalLabel: input.additionalLabel,
    locality: input.locality,
    advisoryMessage: input.advisoryMessage,
    triagePriority: input.triagePriority,
    processingStatus: input.processingStatus,
    executionTimestamp: new Date().toISOString()
  }
};
